Transpose then reverse rows.

void rotate(int[][] matrix) {
    int n = matrix.length;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int temp = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = temp;
        }
    }
    for (int[] row : matrix) {
        Collections.reverse(Arrays.asList(row));
    }
}

Check all primes less than number.

boolean isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

boolean check(int num) {
    for (int i = 2; i <= num / 2; i++) {
        if (isPrime(i) && isPrime(num - i)) return true;
    }
    return false;
}

Recursive solution moves disks between rods.

void hanoi(int n, char from, char to, char aux) {
    if (n == 1) {
        System.out.println("Move disk 1 from " + from + " to " + to);
        return;
    }
    hanoi(n-1, from, aux, to);
    System.out.println("Move disk " + n + " from " + from + " to " + to);
    hanoi(n-1, aux, to, from);
}

Divide and conquer approach.

int binarySearch(int[] arr, int left, int right, int key) {
    if (left > right) return -1;
    int mid = (left + right) / 2;
    if (arr[mid] == key) return mid;
    if (key < arr[mid]) return binarySearch(arr, left, mid - 1, key);
    return binarySearch(arr, mid + 1, right, key);
}

