Use a stack.

def is_valid(s):
    stack = []
    mapping = {')':'(', '}':'{', ']':'['}
    for ch in s:
        if ch in mapping:
            if not stack or stack.pop() != mapping[ch]:
                return False
        else:
            stack.append(ch)
    return not stack

Use sliding window.

def longest_substring(s):
    seen = {}
    left = res = 0
    for right, ch in enumerate(s):
        if ch in seen and seen[ch] >= left:
            left = seen[ch] + 1
        seen[ch] = right
        res = max(res, right - left + 1)
    return res

Sort and merge.

def merge(intervals):
    intervals.sort()
    res = [intervals[0]]
    for start, end in intervals[1:]:
        if start <= res[-1][1]:
            res[-1][1] = max(res[-1][1], end)
        else:
            res.append([start, end])
    return res

