Debouncing delays execution until a function stops being called for a period, while throttling limits execution to once in a fixed interval. Example debounce:
function debounce(fn, delay) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}
